CREATE OR REPLACE FUNCTION public.ca_club_data_player_totals(p_club_id uuid, p_start date, p_end date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE
  r jsonb;
  v_ps date;
  v_pe date;
  v_pc jsonb;
BEGIN
  IF NOT public.fn_ca_club_data_reads_union_basis(p_club_id, p_start, p_end) THEN
    r := public.ca_club_data_player_totals_chicago_basis(p_club_id, p_start, p_end, p_game, p_stakes, p_search);
    IF public.fn_ca_club_data_union_basis(p_club_id) THEN
      r := r || jsonb_build_object('basis_reason', 'window_starts_before_union_basis',
        'union_basis_from', public.fn_ca_club_data_union_basis_from(p_club_id));
    END IF;
    RETURN r;
  END IF;
  r := public.ca_club_data_player_totals_union_basis(p_club_id, p_start, p_end, p_game, p_stakes, p_search);
  RETURN r;
END;$function$

