CREATE OR REPLACE FUNCTION public.ca_club_data_snapshot_v2(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE
  r jsonb;
  v_ps date;
  v_pe date;
  v_pc jsonb;
BEGIN
  IF NOT public.fn_ca_club_data_reads_union_basis(p_club_id, p_start, p_end) THEN
    r := public.ca_club_data_snapshot_v2_chicago_basis(p_club_id, p_start, p_end, p_game, p_stakes, p_search, p_limit);
    IF public.fn_ca_club_data_union_basis(p_club_id) THEN
      r := r || jsonb_build_object('basis_reason', 'window_starts_before_union_basis',
        'union_basis_from', public.fn_ca_club_data_union_basis_from(p_club_id));
    END IF;
    RETURN r;
  END IF;
  r := public.ca_club_data_snapshot_v2_union_basis(p_club_id, p_start, p_end, p_game, p_stakes, p_search, p_limit);
  v_ps := (r->'previous_range'->>'start')::date;
  v_pe := (r->'previous_range'->>'end')::date;
  v_pc := CASE WHEN public.fn_ca_club_data_reads_union_basis(p_club_id, v_ps, v_pe)
               THEN public.fn_ca_club_acct_coverage(p_club_id, v_ps, v_pe)
               ELSE jsonb_build_object('complete', false, 'accounting_basis', 'chicago_net_money_flow',
                      'basis_reason', 'window_starts_before_union_basis') END;
  r := r || jsonb_build_object('previous_coverage', v_pc);
  IF NOT COALESCE((v_pc->>'complete')::boolean, false)
     OR NOT COALESCE((r->'accounting_coverage'->>'complete')::boolean, false) THEN
    r := jsonb_set(r, '{delta}', COALESCE(r->'delta', '{}'::jsonb) || jsonb_build_object(
      'fee_pct', NULL, 'games_pct', NULL, 'winnings_abs', NULL, 'fee_abs', NULL));
  END IF;
  RETURN r;
END;$function$

